import React, { useState, useEffect } from "react";
import { styled } from "@mui/material/styles";
import Button from "@mui/material/Button";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import Grid from "@mui/material/Grid";
import MediaCard from "./MediaCard"; // Import MediaCard here

const VisuallyHiddenInput = styled("input")({
  clip: "rect(0 0 0 0)",
  clipPath: "inset(50%)",
  height: 1,
  overflow: "hidden",
  position: "absolute",
  bottom: 0,
  left: 0,
  whiteSpace: "nowrap",
  width: 1,
});

const PlaceholderImage = styled("div")({
  border: "3px dashed #44CBCB",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  color: "#aaa",
  borderRadius: "10px",
});


const FileUploader = () => {
  const [uploadedImage, setUploadedImage] = useState(null);
  const [apiResponse, setApiResponse] = useState(null); // State for API response

  const handleFileChange = async (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      const imageURL = URL.createObjectURL(selectedFile);
      setUploadedImage(imageURL);

      const formData = new FormData();
      formData.append("file", selectedFile);

      try {
        const response = await fetch("http://127.0.0.1:5000/predict", {
          method: "POST",
          body: formData,
        });

        const data = await response.json();
        console.log("API Response:", data);

        // Assuming data has predicted_class and confidence as per your backend response
        setApiResponse({
          prediction: data.predicted_class,
          confidence: data.confidence,
        });


      } catch (error) {
        console.error("Error fetching API:", error);
      }
    }
  };

  return (
    <Grid container alignItems="center" justifyContent="center" direction="column" spacing={2}>
      <Grid item>
        <input
          onChange={handleFileChange}
          type="file"
          accept=".png, .jpg, .jpeg"
          style={{ display: "none" }}
          id="fileInput"
        />
        <label htmlFor="fileInput">
          <Button component="span" variant="contained" startIcon={<CloudUploadIcon />}>
            Upload an Ultrasound Image
          </Button>
        </label>
      </Grid>
      <Grid item>
        {uploadedImage && <img src={uploadedImage} alt="Uploaded" style={{ maxWidth: "250px", maxHeight: "250px" }} />}
      </Grid>
      <Grid item>
        <MediaCard apiResponse={apiResponse} /> {/* Pass the apiResponse here */}
      </Grid>
    </Grid>
  );
};

export default FileUploader;
